--
-- Table structure for table `linea_espectral`
--

DROP TABLE IF EXISTS `linea_espectral`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `linea_espectral` (
  `id_linea` int unsigned NOT NULL AUTO_INCREMENT,
  `id_espectro` tinyint unsigned NOT NULL,
  `id_nivel_inferior` varchar(20) DEFAULT NULL COMMENT 'Nulo en 215 lineas sin ID de nivel en el NIST',
  `id_nivel_superior` varchar(20) DEFAULT NULL,
  `codigo_tipo_transicion` varchar(4) NOT NULL,
  `codigo_exactitud` varchar(3) DEFAULT NULL COMMENT 'Nulo en las lineas sin Aki documentado',
  `longitud_onda_nm` decimal(18,6) NOT NULL COMMENT 'Valor definitivo: observada, o Ritz si falta',
  `longitud_onda_origen` enum('observada','ritz') NOT NULL,
  `medio` enum('aire','vacio') NOT NULL,
  `longitud_onda_obs_nm` decimal(18,6) DEFAULT NULL COMMENT 'Medida en laboratorio',
  `longitud_onda_ritz_nm` decimal(18,6) DEFAULT NULL COMMENT 'Calculada de la diferencia de niveles',
  `ritz_es_limite` tinyint(1) DEFAULT NULL,
  `incertidumbre_obs_nm` double DEFAULT NULL COMMENT 'Rango real 1.5e-12 a 9e9: DOUBLE, no DECIMAL (mismo motivo que aki_s1)',
  `incertidumbre_ritz_nm` double DEFAULT NULL COMMENT 'Rango real 1.5e-12 a 6e9: DOUBLE, no DECIMAL',
  `aki_s1` double DEFAULT NULL COMMENT 'Coeficiente de Einstein: abarca 35 ordenes de magnitud, por eso DOUBLE y no DECIMAL',
  `fuerza_oscilador_fik` double DEFAULT NULL,
  `log_gf` decimal(10,5) DEFAULT NULL COMMENT 'NO se deriva de g_i*fik: solo coincide en 92.84% de los casos (ver propuesta, seccion 6.3)',
  `intensidad_valor` double DEFAULT NULL COMMENT 'Escala arbitraria propia de cada espectro',
  `intensidad_bandera` varchar(40) DEFAULT NULL COMMENT 'Bandera de calidad de la linea (*, a, a*, bl(O II,N II)*, ...)',
  `energia_inferior_cm1` decimal(18,6) DEFAULT NULL,
  `energia_superior_cm1` decimal(18,6) DEFAULT NULL,
  `energia_inferior_interpolada` tinyint(1) DEFAULT NULL,
  `energia_superior_interpolada` tinyint(1) DEFAULT NULL,
  `energia_inferior_origen_desconocido` tinyint(1) DEFAULT NULL,
  `energia_superior_origen_desconocido` tinyint(1) DEFAULT NULL,
  `medicion_repetida` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'TRUE si esta misma transicion fue publicada por mas de una fuente',
  PRIMARY KEY (`id_linea`),
  KEY `idx_linea_espectro` (`id_espectro`),
  KEY `idx_linea_nivel_inferior` (`id_nivel_inferior`),
  KEY `idx_linea_nivel_superior` (`id_nivel_superior`),
  KEY `idx_linea_tipo_transicion` (`codigo_tipo_transicion`),
  KEY `idx_linea_exactitud` (`codigo_exactitud`),
  CONSTRAINT `fk_linea_espectro` FOREIGN KEY (`id_espectro`) REFERENCES `espectro` (`id_espectro`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_linea_exactitud` FOREIGN KEY (`codigo_exactitud`) REFERENCES `exactitud` (`codigo`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_linea_nivel_inferior` FOREIGN KEY (`id_nivel_inferior`) REFERENCES `nivel_energia` (`id_nivel`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_linea_nivel_superior` FOREIGN KEY (`id_nivel_superior`) REFERENCES `nivel_energia` (`id_nivel`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_linea_tipo_transicion` FOREIGN KEY (`codigo_tipo_transicion`) REFERENCES `tipo_transicion` (`codigo`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_linea_aki_positivo` CHECK (((`aki_s1` is null) or (`aki_s1` > 0))),
  CONSTRAINT `chk_linea_energia_superior_mayor` CHECK (((`energia_superior_cm1` is null) or (`energia_inferior_cm1` is null) or (`energia_superior_cm1` > `energia_inferior_cm1`))),
  CONSTRAINT `chk_linea_longitud_onda_positiva` CHECK ((`longitud_onda_nm` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=18289 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Lineas espectrales: transiciones electronicas entre dos niveles de energia';
/*!40101 SET character_set_client = @saved_cs_client */;

