--
-- Table structure for table `linea_referencia`
--

DROP TABLE IF EXISTS `linea_referencia`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `linea_referencia` (
  `id_linea` int unsigned NOT NULL,
  `codigo_referencia` varchar(20) NOT NULL,
  `rol` enum('probabilidad','longitud_onda') NOT NULL COMMENT 'La misma publicacion puede ser fuente de dos hechos distintos de la misma linea',
  PRIMARY KEY (`id_linea`,`codigo_referencia`,`rol`),
  KEY `idx_linea_referencia_codigo` (`codigo_referencia`),
  CONSTRAINT `fk_linea_referencia_linea` FOREIGN KEY (`id_linea`) REFERENCES `linea_espectral` (`id_linea`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_linea_referencia_referencia` FOREIGN KEY (`codigo_referencia`) REFERENCES `referencia` (`codigo`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='N:M entre linea_espectral y referencia. Resuelve las listas separadas por comas de tp_ref/line_ref';
/*!40101 SET character_set_client = @saved_cs_client */;

