--
-- Table structure for table `nivel_energia`
--

DROP TABLE IF EXISTS `nivel_energia`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `nivel_energia` (
  `id_nivel` varchar(20) NOT NULL COMMENT 'Level ID del NIST, ej. 006002.000001. VARCHAR para no perder los ceros a la izquierda',
  `id_espectro` tinyint unsigned NOT NULL,
  `configuracion` varchar(80) DEFAULT NULL COMMENT 'Configuracion electronica, ej. 2s2.2p2.(3P).3d',
  `termino` varchar(20) DEFAULT NULL COMMENT 'Termino espectroscopico, ej. 2P*',
  `j_valor` decimal(4,1) DEFAULT NULL COMMENT 'Momento angular total (1.5 para 3/2)',
  `j_texto` varchar(20) DEFAULT NULL COMMENT 'Valor original de J, incluidos los no resueltos',
  `j_resuelto` tinyint(1) DEFAULT NULL COMMENT 'FALSE si el NIST no determino un unico valor de J',
  `g` smallint unsigned DEFAULT NULL COMMENT 'Degeneracion estadistica del nivel',
  `energia_ev` decimal(18,9) DEFAULT NULL,
  `energia_interpolada` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'TRUE si la energia es calculada/teorica, no medida',
  `incertidumbre_ev` decimal(18,12) DEFAULT NULL,
  PRIMARY KEY (`id_nivel`),
  KEY `idx_nivel_espectro` (`id_espectro`),
  CONSTRAINT `fk_nivel_espectro` FOREIGN KEY (`id_espectro`) REFERENCES `espectro` (`id_espectro`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_nivel_degeneracion` CHECK (((`j_valor` is null) or (`g` is null) or (`g` = ((2 * `j_valor`) + 1))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Niveles de energia atomicos (escalones internos del atomo)';
/*!40101 SET character_set_client = @saved_cs_client */;

